  return s;
}
const mutExec = (exitCode, calls = []) => (command, { logFile, env }) => {
  calls.push({ command, env });
  fs.appendFileSync(logFile, command === 'node mutate.js' ? 'mutantes\\n' : 'ok\\n');
  return { exit: command === 'node mutate.js' ? exitCode : 0 };
};

